import React, { useState, useEffect } from "react";
import { supabase } from "./supabaseClient";
import Login from "./Login";
import Papa from "papaparse";
import * as XLSX from "xlsx";
import { PieChart, Pie, Cell, Tooltip, Legend, BarChart, Bar, XAxis, YAxis, CartesianGrid, ResponsiveContainer } from "recharts";

const COLORS = ["#8884d8", "#82ca9d", "#ffc658", "#ffb86c", "#5aa9fa", "#fa5a7d", "#16a085"];

const renderCustomLabel = ({ cx, cy, midAngle, innerRadius, outerRadius, percent }) => {
  const RADIAN = Math.PI / 180;
  const radius = innerRadius + (outerRadius - innerRadius) * 0.5;
  const x = cx + radius * Math.cos(-midAngle * RADIAN);
  const y = cy + radius * Math.sin(-midAngle * RADIAN);
  return (
    <text x={x} y={y} fill="#111" fontWeight="bold" fontSize={20} textAnchor="middle" dominantBaseline="middle">
      {percent > 0 ? `${(percent * 100).toFixed(0)}%` : ""}
    </text>
  );
};

function App() {
  const [user, setUser] = useState(null);
  const [showLogin, setShowLogin] = useState(false);
  const [data, setData] = useState([]);
  const [summary, setSummary] = useState({});
  const [visits, setVisits] = useState(0);
  const [loading, setLoading] = useState(true);
  const [uploading, setUploading] = useState(false);

  useEffect(() => {
    supabase.auth.getSession().then(({ data }) => {
      setUser(data?.session?.user || null);
    });
    const { data: listener } = supabase.auth.onAuthStateChange((_event, session) => {
      setUser(session?.user || null);
    });
    return () => listener?.subscription.unsubscribe();
  }, []);

  useEffect(() => {
    if (user) {
      fetchLatestReport();
    } else {
      setLoading(false);
    }
  }, [user]);

  async function fetchLatestReport() {
    try {
      setLoading(true);
      const { data, error } = await supabase
        .from("order_reports")
        .select("*")
        .order("created_at", { ascending: false })
        .limit(1);

      if (data && data.length) {
        const report = data[0];
        setData(report.report_data.rows || []);
        let summaryObj = report.report_data.summary;
        if (typeof summaryObj === "string") {
          try {
            summaryObj = JSON.parse(summaryObj);
          } catch {
            summaryObj = {};
          }
        }
        setSummary(summaryObj || {});
        setVisits(report.visits || 0);
      } else {
        setData([]);
        setSummary({});
        setVisits(0);
      }
    } catch (err) {
      console.error("Error fetching report:", err);
    } finally {
      setLoading(false);
    }
  }

  // رفع ملف جديد (CSV أو Excel)
  const handleFileUpload = (e) => {
    const file = e.target.files[0];
    if (!file) return;
    const fileName = file.name.toLowerCase();
    if (fileName.endsWith(".csv")) {
      Papa.parse(file, {
        header: true,
        skipEmptyLines: true,
        complete: function (results) {
          processAndUploadReport(results.data, file.name);
        },
      });
    } else if (fileName.endsWith(".xlsx") || fileName.endsWith(".xls")) {
      const reader = new FileReader();
      reader.onload = (evt) => {
        const data = new Uint8Array(evt.target.result);
        const workbook = XLSX.read(data, { type: "array" });
        const firstSheet = workbook.Sheets[workbook.SheetNames[0]];
        const jsonData = XLSX.utils.sheet_to_json(firstSheet, { defval: "" });
        processAndUploadReport(jsonData, file.name);
      };
      reader.readAsArrayBuffer(file);
    } else {
      alert("الرجاء رفع ملف CSV أو Excel فقط!");
    }
  };

  // معالجة ورفع التقرير
  async function processAndUploadReport(rows, fileName) {
    setUploading(true);

    // إجمالي المبيعات من teest أو Grand Total (Base)
    let totalSales = 0;
    let paymentMethods = { "تابي": 0, "تمارا": 0, "مدفوع": 0, "بطاقة ائتمانية": 0 };
    let paymentTotals = { "تابي": 0, "تمارا": 0, "مدفوع": 0, "بطاقة ائتمانية": 0 };
    let orderTypes = { "اندرويد": 0, "ايفون": 0, "ويب": 0 };
    let shippingTable = {};
    let productOrders = {};
    let regionOrders = {};

    // ----- إمارات -----
    let uaeTotalSales = 0;
    let uaeProductOrders = {};

    rows.forEach(row => {
      // اجمالي المبيعات (غير اسم العمود حسب ملفك)
      let value = (row["teest"] || row["Grand Total (Base)"] || "0").toString().replace(/,/g, "").trim();
      let total = parseFloat(value);
      if (!isNaN(total)) totalSales += total;

      // طرق الدفع
      let pay = (row["Payment Method"] || "").toLowerCase();
      let payType = "";
      if (pay.includes("madfu")) payType = "مدفوع";
      else if (pay.includes("credit") || pay.includes("debit") || pay.includes("apple")) payType = "بطاقة ائتمانية";
      else if (pay.includes("tamara")) payType = "تمارا";
      else if (pay.includes("pay in 4") || pay.includes("tabby")) payType = "تابي";
      if (payType) {
        paymentMethods[payType] += 1;
        if (!isNaN(total)) paymentTotals[payType] += total;
      }

      // مصدر الطلب
      let type = (row["Order Type"] || "").toLowerCase();
      if (type.includes("android")) orderTypes["اندرويد"] += 1;
      else if (type.includes("ios")) orderTypes["ايفون"] += 1;
      else if (type) orderTypes["ويب"] += 1;

      // وسيلة الشحن
      let shipping = row["Shipping Information"] || "";
      if (shipping) shippingTable[shipping] = (shippingTable[shipping] || 0) + 1;

      // المنتجات الأكثر مبيعاً (Product Details)
      let details = row["Product Details"] || "";
      const items = details.split("|").filter((x) => x.startsWith("Name:"));
      items.forEach((item) => {
        let name = item.replace("Name:", "").trim();
        if (name) productOrders[name] = (productOrders[name] || 0) + 1;
      });

      // أكثر 5 مدن
      let region = (row["Region"] || row[" Region"] || "").trim();
      if (region) regionOrders[region] = (regionOrders[region] || 0) + 1;

      // -- إمارات --
      let country = (row["Country"] || "").toUpperCase();
      if (country.includes("AE")) {
        if (!isNaN(total)) uaeTotalSales += total;
        items.forEach((item) => {
          let name = item.replace("Name:", "").trim();
          if (name) uaeProductOrders[name] = (uaeProductOrders[name] || 0) + 1;
        });
      }
    });

    const reportSummary = {
      totalSales,
      paymentMethods,
      paymentTotals,
      orderTypes,
      shippingTable,
      productOrders,
      regionOrders,
      uaeTotalSales,
      uaeProductOrders
    };

    const { error } = await supabase.from("order_reports").insert([
      {
        report_data: { rows, summary: reportSummary },
        visits,
        report_file_name: fileName,
      },
    ]);
    setUploading(false);
    if (error) {
      alert("حدث خطأ أثناء رفع التقرير: " + error.message);
    } else {
      fetchLatestReport();
      alert("تم رفع التقرير بنجاح!");
    }
  }

  // PieChart data
  const paymentData = Object.entries(summary.paymentMethods || {}).map(([name, value]) => ({ name, value }));
  const orderTypeData = Object.entries(summary.orderTypes || {}).map(([name, value]) => ({ name, value }));

  // متوسط السلة حسب وسيلة الدفع
  const avgBasketData = Object.entries(summary.paymentMethods || {}).map(([payType, count]) => {
    const total = (summary.paymentTotals && summary.paymentTotals[payType]) || 0;
    const avg = count > 0 ? (total / count) : 0;
    return { name: payType, متوسط_السلة: Number(avg.toFixed(2)) };
  });

  // جداول
  const shippingTableArr = Object.entries(summary.shippingTable || {})
    .sort((a, b) => b[1] - a[1])
    .map(([name, orders]) => ({ name, orders }));

  const topProducts = Object.entries(summary.productOrders || {})
    .sort((a, b) => b[1] - a[1])
    .slice(0, 10)
    .map(([name, orders]) => ({ name, orders }));

  const topRegions = Object.entries(summary.regionOrders || {})
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([name, orders]) => ({ name, orders }));

  // جداول وتقارير الإمارات
  const uaeTotalSales = summary.uaeTotalSales || 0;
  const uaeTopProducts = Object.entries(summary.uaeProductOrders || {})
    .sort((a, b) => b[1] - a[1])
    .slice(0, 5)
    .map(([name, orders]) => ({ name, orders }));

  return (
    <div style={{ fontFamily: "Tahoma, Arial, sans-serif", direction: "rtl", background: "#fafafa", minHeight: "100vh", padding: "32px" }}>
      {/* زر تسجيل الدخول أو تسجيل الخروج */}
      <div style={{ position: "fixed", top: 18, right: 32, zIndex: 2001 }}>
        {!user && (
          <button
            onClick={() => setShowLogin(true)}
            style={{
              fontSize: 18,
              background: "#16a085",
              color: "#fff",
              border: "none",
              borderRadius: 12,
              padding: "8px 20px",
              cursor: "pointer"
            }}
          >
            تسجيل الدخول
          </button>
        )}
        {user && (
          <button
            onClick={async () => {
              await supabase.auth.signOut();
              setUser(null);
            }}
            style={{
              fontSize: 15,
              background: "#fa5a7d",
              color: "#fff",
              border: "none",
              borderRadius: 12,
              padding: "6px 14px",
              cursor: "pointer",
              marginRight: 8
            }}
          >
            تسجيل الخروج
          </button>
        )}
      </div>
      {/* نافذة تسجيل الدخول */}
      {showLogin && <Login onClose={() => setShowLogin(false)} />}
      <h1 style={{ textAlign: "center", marginBottom: 24 }}>لوحة تقارير الطلبات</h1>
      <div style={{ display: "flex", justifyContent: "center", marginBottom: 20, gap: 12 }}>
        <label>
          <span>عدد الزيارات:</span>
          <input
            type="number"
            min={0}
            value={visits}
            onChange={e => setVisits(Number(e.target.value))}
            style={{ margin: "0 8px", padding: "6px 16px", fontSize: 16, width: 110, borderRadius: 8, border: "1px solid #ddd" }}
          />
        </label>
        {user && (
          <input type="file" accept=".csv,.xlsx,.xls" onChange={handleFileUpload} style={{ marginRight: 16 }} />
        )}
      </div>
      <div style={{ display: "flex", justifyContent: "center", marginBottom: 28 }}>
        <div style={{ background: "white", boxShadow: "0 2px 8px #eee", borderRadius: 20, padding: "18px 32px", fontSize: 30, color: "#16a085", fontWeight: "bold", margin: "0 8px" }}>
          إجمالي المبيعات
          <div style={{ fontSize: 40 }}>{(summary.totalSales || 0).toLocaleString()} ريال</div>
        </div>
      </div>
      <div style={{ display: "flex", flexWrap: "wrap", gap: 30, justifyContent: "center", marginBottom: 40 }}>
        <div style={{ background: "white", borderRadius: 20, boxShadow: "0 2px 8px #eee", padding: 24 }}>
          <h3 style={{ textAlign: "center" }}>طريقة الدفع</h3>
          <PieChart width={320} height={250}>
            <Pie
              data={paymentData}
              cx="50%"
              cy="50%"
              labelLine={false}
              outerRadius={90}
              fill="#8884d8"
              dataKey="value"
              label={renderCustomLabel}
            >
              {paymentData.map((entry, index) => (
                <Cell key={`cell-pay-${index}`} fill={COLORS[index % COLORS.length]} />
              ))}
            </Pie>
            <Tooltip />
            <Legend />
          </PieChart>
        </div>
        {/* مصدر الطلب PieChart (اندرويد/ايفون/ويب) */}
        <div style={{ background: "white", borderRadius: 20, boxShadow: "0 2px 8px #eee", padding: 24 }}>
          <h3 style={{ textAlign: "center" }}>مصدر الطلب (اندرويد/ايفون/ويب)</h3>
          <PieChart width={320} height={250}>
            <Pie
              data={orderTypeData}
              cx="50%"
              cy="50%"
              labelLine={false}
              outerRadius={90}
              fill="#82ca9d"
              dataKey="value"
              label={renderCustomLabel}
            >
              {orderTypeData.map((entry, index) => (
                <Cell key={`cell-ordertype-${index}`} fill={COLORS[index % COLORS.length]} />
              ))}
            </Pie>
            <Tooltip />
            <Legend />
          </PieChart>
        </div>
        {/* رسم متوسط السلة حسب وسيلة الدفع */}
        <div style={{ background: "white", borderRadius: 20, boxShadow: "0 2px 8px #eee", padding: 24, minWidth: 340 }}>
          <h3 style={{ textAlign: "center" }}>متوسط السلة حسب وسيلة الدفع</h3>
          <ResponsiveContainer width={300} height={230}>
            <BarChart data={avgBasketData}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" fontSize={14} />
              <YAxis fontSize={14} />
              <Tooltip />
              <Bar dataKey="متوسط_السلة">
                {avgBasketData.map((entry, index) => (
                  <Cell key={`cell-avg-${index}`} fill={COLORS[index % COLORS.length]} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </div>
      </div>
      {/* جدول وسيلة الشحن */}
      <div style={{
        background: "white", boxShadow: "0 2px 8px #eee", borderRadius: 20, padding: 24,
        maxWidth: 500, margin: "40px auto"
      }}>
        <h3 style={{ textAlign: "center" }}>جدول أنواع الشحن وعدد الطلبات</h3>
        <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "center", fontSize: 18 }}>
          <thead>
            <tr style={{ background: "#f1f1f1" }}>
              <th style={{ padding: 8 }}>وسيلة الشحن</th>
              <th style={{ padding: 8 }}>عدد الطلبات</th>
            </tr>
          </thead>
          <tbody>
            {shippingTableArr.map((ship, idx) => (
              <tr key={ship.name} style={{ borderBottom: "1px solid #f1f1f1" }}>
                <td>{ship.name}</td>
                <td>{ship.orders}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {/* جدول أكثر المنتجات مبيعًا */}
      <div style={{
        background: "white", boxShadow: "0 2px 8px #eee", borderRadius: 20, padding: 24,
        maxWidth: 600, margin: "40px auto"
      }}>
        <h3 style={{ textAlign: "center" }}>أكثر 10 منتجات طلبًا</h3>
        <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "center", fontSize: 18 }}>
          <thead>
            <tr style={{ background: "#f1f1f1" }}>
              <th style={{ padding: 8 }}>الترتيب</th>
              <th style={{ padding: 8 }}>المنتج</th>
              <th style={{ padding: 8 }}>عدد الطلبات</th>
            </tr>
          </thead>
          <tbody>
            {topProducts.map((prod, idx) => (
              <tr key={prod.name} style={{ borderBottom: "1px solid #f1f1f1" }}>
                <td>{idx + 1}</td>
                <td>{prod.name}</td>
                <td>{prod.orders}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {/* جدول أكثر المدن طلبًا */}
      <div style={{
        background: "white", boxShadow: "0 2px 8px #eee", borderRadius: 20, padding: 24,
        maxWidth: 400, margin: "40px auto"
      }}>
        <h3 style={{ textAlign: "center" }}>أكثر 5 مدن طلبًا</h3>
        <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "center", fontSize: 18 }}>
          <thead>
            <tr style={{ background: "#f1f1f1" }}>
              <th style={{ padding: 8 }}>الترتيب</th>
              <th style={{ padding: 8 }}>المدينة</th>
              <th style={{ padding: 8 }}>عدد الطلبات</th>
            </tr>
          </thead>
          <tbody>
            {topRegions.map((city, idx) => (
              <tr key={city.name} style={{ borderBottom: "1px solid #f1f1f1" }}>
                <td>{idx + 1}</td>
                <td>{city.name}</td>
                <td>{city.orders}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {/* تقارير متجر الإمارات */}
      <div style={{
        background: "#e6f4f1", boxShadow: "0 2px 8px #cce1de", borderRadius: 20, padding: 24,
        maxWidth: 600, margin: "60px auto 0"
      }}>
        <h2 style={{ textAlign: "center", color: "#049790" }}>تقرير متجر الإمارات 🇦🇪</h2>
        <div style={{ fontSize: 22, marginBottom: 14, marginTop: 16 }}>
          <strong>إجمالي مبيعات الإمارات:</strong> {uaeTotalSales.toLocaleString()} ريال
        </div>
        <div>
          <h3 style={{ textAlign: "center", color: "#049790" }}>أكثر 5 منتجات طلبًا في الإمارات</h3>
          <table style={{ width: "100%", borderCollapse: "collapse", textAlign: "center", fontSize: 18 }}>
            <thead>
              <tr style={{ background: "#f1f1f1" }}>
                <th style={{ padding: 8 }}>الترتيب</th>
                <th style={{ padding: 8 }}>المنتج</th>
                <th style={{ padding: 8 }}>عدد الطلبات</th>
              </tr>
            </thead>
            <tbody>
              {uaeTopProducts.length === 0 && (
                <tr><td colSpan={3}>لا توجد بيانات</td></tr>
              )}
              {uaeTopProducts.map((prod, idx) => (
                <tr key={prod.name} style={{ borderBottom: "1px solid #f1f1f1" }}>
                  <td>{idx + 1}</td>
                  <td>{prod.name}</td>
                  <td>{prod.orders}</td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
      {(loading || uploading) && (
        <div style={{
          position: "fixed", top: 0, left: 0, width: "100vw", height: "100vh",
          background: "rgba(255,255,255,0.6)", display: "flex", alignItems: "center", justifyContent: "center", zIndex: 9999
        }}>
          <div style={{ fontSize: 28, color: "#049790" }}>جاري التحميل...</div>
        </div>
      )}
    </div>
  );
}

export default App;
